param([switch]$Silent)

# =============================================================================
# TGS MASTER AUDIT TOOL v9.6.1 (IP & BLANK DATA FIX)
# -----------------------------------------------------------------------------
# 1. FIXED: IP, MAC, and Network now use a "Backup Method" so they are never blank.
# 2. FIXED: IP Address now uploads correctly to the Sheet.
# 3. NO CHANGES: All other v9.6 features (Schedule, Colors) are exactly the same.
# =============================================================================

# --- CONFIGURATION ---
$GoogleAPI = "https://script.google.com/macros/s/AKfycbz6Q-tcoC7hag43zyW0UzyCKbJ_m_EkB5c1IBo5kDC082kOKburY0DabWD92g_vd3JP/exec"
$UserConfigPath = "$env:APPDATA\TGS_AssignedUser.txt"
$SecurityConfigPath = "$env:APPDATA\TGS_StrictDomains.txt"
$BgBase64 = "" 


# --- NEW: ROBUST NETWORK DETECTION FUNCTION ---
function Get-NetInfo {
    # Method 1: Standard Modern Detection
    $N = Get-NetIPConfiguration | Where {$_.IPv4DefaultGateway -ne $null} | Select -First 1
    if ($N) { return @{IP=$N.IPv4Address.IPAddress; MAC=$N.NetAdapter.MacAddress; Desc=$N.InterfaceAlias} }
    
    # Method 2: Backup WMI Detection (Fixes "Blank" issues)
    $W = Get-CimInstance Win32_NetworkAdapterConfiguration | Where {$_.IPEnabled -eq $true} | Select -First 1
    if ($W) { return @{IP=$W.IPAddress[0]; MAC=$W.MACAddress; Desc=$W.Description} }
    
    return @{IP="N/A"; MAC="N/A"; Desc="Not Connected"}
}

# =============================================================================
# PART 1: SILENT SCHEDULER (MONDAY & FRIDAY 12:00 PM)
# =============================================================================
if ($Silent) {
    try {
        $PCName = $env:COMPUTERNAME
        $tUser = if (Test-Path $UserConfigPath) { (Get-Content $UserConfigPath -Raw).Trim() } else { $env:USERNAME }
        
        # USE ROBUST DETECTION
        $NetData = Get-NetInfo
        
        $USB = if((Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Services\USBSTOR" "Start" -EA 0).Start -eq 4){"BLOCKED"}else{"ALLOWED"}
        $RDP = if((Get-ItemProperty "HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\Terminal Services" "fDisableClip" -EA 0).fDisableClip -eq 1){"BLOCKED"}else{"ALLOWED"}
        $Web = if((Get-ItemProperty "HKLM:\SOFTWARE\Policies\Google\Chrome" "AllowedDomainsForApps" -EA 0).AllowedDomainsForApps){"BLOCKED"}else{"ALLOWED"}

        $Body = @{
            Targets       = @("SCHEDULE Audit")
            AssignedUser  = $tUser
            PCName        = $PCName
            IP            = $NetData.IP
            USBStatus     = $USB
            RDPStatus     = $RDP
            BrowserDomain = $Web
            TTCode        = "Scheduled Success"
        } | ConvertTo-Json
        
        [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.SecurityProtocolType]::Tls12
        Invoke-RestMethod -Uri $GoogleAPI -Method POST -Body $Body -ContentType "application/json"
    } catch {}
    Exit
}

