# --- FUNCTIONS ---
function Get-ImageFromBase64($S){if(!$S){return $null}try{ $B=[Convert]::FromBase64String($S); $M=New-Object System.IO.MemoryStream($B,0,$B.Length); return [System.Drawing.Image]::FromStream($M) }catch{return $null}}
function Get-USBStatus { $v=Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Services\USBSTOR" "Start" -EA SilentlyContinue; if($v -and $v.Start -eq 4){"BLOCKED"}else{"ALLOWED"} }
function Set-USB ($Block) { $p="HKLM:\SYSTEM\CurrentControlSet\Services\USBSTOR"; if(!(Test-Path $p)){return}; if($Block){Set-ItemProperty $p "Start" 4}else{Set-ItemProperty $p "Start" 3} }
function Get-RDPClipStatus { $v=Get-ItemProperty "HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\Terminal Services" "fDisableClip" -EA SilentlyContinue; if($v -and $v.fDisableClip -eq 1){"BLOCKED"}else{"ALLOWED"} }
function Set-RDPClip ($Block) { $p="HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\Terminal Services"; if(!(Test-Path $p)){New-Item $p -Force|Out-Null}; if($Block){Set-ItemProperty $p "fDisableClip" 1}else{Remove-ItemProperty $p "fDisableClip" -EA SilentlyContinue} }
function Get-BrowserPolicyStatus { $v=Get-ItemProperty "HKLM:\SOFTWARE\Policies\Google\Chrome" "AllowedDomainsForApps" -ErrorAction SilentlyContinue; if($v -and $v.AllowedDomainsForApps){"BLOCKED"}else{"ALLOWED"} }
function Close-Browsers { $b=@("chrome","msedge","brave","opera","firefox"); foreach($p in $b){Stop-Process -Name $p -Force -EA SilentlyContinue} }

function Set-CorporatePolicy ($DomainList, $Remove=$false) {
    $ChromiumKeys = @("HKLM:\SOFTWARE\Policies\Google\Chrome","HKLM:\SOFTWARE\Policies\Microsoft\Edge","HKLM:\SOFTWARE\Policies\BraveSoftware\Brave")
    $FirefoxPath = "HKLM:\SOFTWARE\Policies\Mozilla\Firefox"; $FirefoxFilter = "$FirefoxPath\WebsiteFilter"
    $WebDomains = @(); $FirefoxExceptions = @(); $ProfileRegex = @()
    foreach ($d in $DomainList) { 
        $clean = $d.Trim() -replace "\*@", "" 
        if ($clean) { 
            $WebDomains += $clean; $FirefoxExceptions += "https://$clean"; $FirefoxExceptions += "https://www.$clean"
            if ($clean -match "gmail.com" -or $clean -match "google.com") { if ($WebDomains -notcontains "accounts.google.com") { $WebDomains += "accounts.google.com" }; $FirefoxExceptions += "https://accounts.google.com"; $FirefoxExceptions += "https://mail.google.com" }
            $reg = $d.Trim() -replace "\.", "\." -replace "\*", ".*"; $ProfileRegex += $reg
        } 
    }
    $WebString = $WebDomains -join ","; $ProfileString = $ProfileRegex -join "|"
    foreach ($k in $ChromiumKeys) {
        if (-not (Test-Path $k)) { New-Item -Path $k -Force | Out-Null }
        Remove-ItemProperty -Path $k -Name "IncognitoModeAvailability" -EA 0; Remove-ItemProperty -Path $k -Name "BrowserGuestModeEnabled" -EA 0
        if ($Remove) { Remove-ItemProperty -Path $k -Name "AllowedDomainsForApps" -EA 0; Remove-ItemProperty -Path $k -Name "RestrictSigninToPattern" -EA 0 } 
        else { New-ItemProperty -Path $k -Name "AllowedDomainsForApps" -Value $WebString -PropertyType String -Force | Out-Null; New-ItemProperty -Path $k -Name "RestrictSigninToPattern" -Value $ProfileString -PropertyType String -Force | Out-Null }
    }
    if ($Remove) { Remove-Item -Path $FirefoxPath -Recurse -Force -EA 0 } 
    else {
        if (!(Test-Path $FirefoxFilter\Exceptions)) { New-Item -Path "$FirefoxFilter\Exceptions" -Force | Out-Null }
        Set-ItemProperty -Path $FirefoxPath -Name "AllowedDomainsForApps" -Value $WebString -Type String -Force; Set-ItemProperty -Path "$FirefoxFilter\Block" -Name "1" -Value "*" -Type String -Force
        Remove-Item "$FirefoxFilter\Exceptions\*" -Force -EA 0; $count = 1; foreach ($site in $FirefoxExceptions) { Set-ItemProperty -Path "$FirefoxFilter\Exceptions" -Name "$count" -Value $site -Type String -Force; $count++ }
    }
}

