$lblWebStatus = New-Object System.Windows.Forms.Label; $lblWebStatus.Location=New-Object System.Drawing.Point(20,290); $lblWebStatus.AutoSize=$true; $lblWebStatus.Font=New-Object System.Drawing.Font("Segoe UI",11,[System.Drawing.FontStyle]::Bold); $lblWebStatus.BackColor="Transparent"; $pnlSec.Controls.Add($lblWebStatus)
Update-StatusLabel $lblWebStatus (Get-BrowserPolicyStatus) # Init Color

$txtInputS = New-Object System.Windows.Forms.TextBox; $txtInputS.Text="*@outlook.com"; $txtInputS.Location=New-Object System.Drawing.Point(20, 320); $txtInputS.Size=New-Object System.Drawing.Size(300, 30); $pnlSec.Controls.Add($txtInputS)
$btnAddS = New-Object System.Windows.Forms.Button; $btnAddS.Text="ADD"; $btnAddS.BackColor="SteelBlue"; $btnAddS.ForeColor="White"; $btnAddS.FlatStyle="Flat"; $btnAddS.Location=New-Object System.Drawing.Point(330, 319); $btnAddS.Size=New-Object System.Drawing.Size(80, 29); $pnlSec.Controls.Add($btnAddS)
$btnDelS = New-Object System.Windows.Forms.Button; $btnDelS.Text="REMOVE"; $btnDelS.BackColor="IndianRed"; $btnDelS.ForeColor="White"; $btnDelS.FlatStyle="Flat"; $btnDelS.Location=New-Object System.Drawing.Point(420, 319); $btnDelS.Size=New-Object System.Drawing.Size(100, 29); $pnlSec.Controls.Add($btnDelS)
$lstDomains = New-Object System.Windows.Forms.ListBox; $lstDomains.Location=New-Object System.Drawing.Point(20, 360); $lstDomains.Size=New-Object System.Drawing.Size(500, 150); $lstDomains.BackColor=[System.Drawing.Color]::FromArgb(60, 60, 70); $lstDomains.ForeColor="White"; $pnlSec.Controls.Add($lstDomains)
$btnApply = New-Object System.Windows.Forms.Button; $btnApply.Text="APPLY FIX"; $btnApply.BackColor="SeaGreen"; $btnApply.ForeColor="White"; $btnApply.FlatStyle="Flat"; $btnApply.Location=New-Object System.Drawing.Point(20, 530); $btnApply.Size=New-Object System.Drawing.Size(500, 50); $pnlSec.Controls.Add($btnApply)
$btnReset = New-Object System.Windows.Forms.Button; $btnReset.Text="RESET RULES"; $btnReset.BackColor="Salmon"; $btnReset.ForeColor="White"; $btnReset.FlatStyle="Flat"; $btnReset.Location=New-Object System.Drawing.Point(20, 590); $btnReset.Size=New-Object System.Drawing.Size(500, 40); $pnlSec.Controls.Add($btnReset)
$btnSaveList = New-Object System.Windows.Forms.Button; $btnSaveList.Text="SAVE LIST"; $btnSaveList.BackColor="DimGray"; $btnSaveList.ForeColor="White"; $btnSaveList.FlatStyle="Flat"; $btnSaveList.Location=New-Object System.Drawing.Point(540, 360); $btnSaveList.Size=New-Object System.Drawing.Size(120, 40); $pnlSec.Controls.Add($btnSaveList)

# EVENTS
$btnUSBBlock.Add_Click({ Set-USB $true; Update-StatusLabel $lblUSB "BLOCKED" }); $btnUSBAllow.Add_Click({ Set-USB $false; Update-StatusLabel $lblUSB "ALLOWED" })
$btnRDPBlock.Add_Click({ Set-RDPClip $true; Update-StatusLabel $lblRDP "BLOCKED" }); $btnRDPAllow.Add_Click({ Set-RDPClip $false; Update-StatusLabel $lblRDP "ALLOWED" })
$btnSchEn.Add_Click({ 
    $A=New-ScheduledTaskAction -Execute "PowerShell" -Argument "-WindowStyle Hidden -Exec Bypass -File `"$PSCommandPath`" -Silent"
    # SCHEDULE: MON & FRI at 12:00 PM
    $T=New-ScheduledTaskTrigger -Weekly -DaysOfWeek Monday,Friday -At 12:00PM
    Register-ScheduledTask "TGS_Weekly_Audit" -Action $A -Trigger $T -User "SYSTEM" -RunLevel Highest -Force; $lblSched.Text="Status: ACTIVE"; [System.Windows.Forms.MessageBox]::Show("Schedule Set Successfully.", "Success") 
})
$btnSchDis.Add_Click({ Unregister-ScheduledTask "TGS_Weekly_Audit" -Confirm:$false -EA SilentlyContinue; $lblSched.Text="Status: INACTIVE"; [System.Windows.Forms.MessageBox]::Show("Schedule Disabled", "Done") })
$btnTestSilent.Add_Click({ [System.Windows.Forms.MessageBox]::Show("Running Silent Scan -> 'SCHEDULE Audit' tab.", "Testing"); Start-Process PowerShell -ArgumentList "-WindowStyle Hidden -ExecutionPolicy Bypass -File `"$PSCommandPath`" -Silent" })
$btnAddS.Add_Click({ if($txtInputS.Text -and -not ($lstDomains.Items.Contains($txtInputS.Text))) { $lstDomains.Items.Add($txtInputS.Text) } }); $btnDelS.Add_Click({ if($lstDomains.SelectedItem) { $lstDomains.Items.Remove($lstDomains.SelectedItem) } }); $btnSaveList.Add_Click({ $arr=@(); foreach($i in $lstDomains.Items){$arr+=$i}; $arr|Set-Content $SecurityConfigPath; [System.Windows.Forms.MessageBox]::Show("List saved!", "Success") })
$btnApply.Add_Click({ $arr=@(); foreach($i in $lstDomains.Items){$arr+=$i}; if($arr.Count -eq 0){[System.Windows.Forms.MessageBox]::Show("Add domain first.", "Error")}else{ $btnApply.Text="Applying..."; $form.Refresh(); $arr|Set-Content $SecurityConfigPath; Set-CorporatePolicy $arr; Close-Browsers; [System.Windows.Forms.MessageBox]::Show("POLICY APPLIED!", "Done"); $btnApply.Text="APPLY FIX" } })
$btnReset.Add_Click({ Set-CorporatePolicy "" $true; Close-Browsers; [System.Windows.Forms.MessageBox]::Show("Rules Removed.", "Done") })
$btnTabHard.Add_Click({ $pnlHard.Visible=$true; $pnlSec.Visible=$false; $btnTabHard.BackColor=[System.Drawing.Color]::FromArgb(20,30,50); $btnTabHard.ForeColor="LightSkyBlue"; $btnTabSec.BackColor="Transparent"; $btnTabSec.ForeColor="Gray" }); $btnTabSec.Add_Click({ $pnlHard.Visible=$false; $pnlSec.Visible=$true; $btnTabSec.BackColor=[System.Drawing.Color]::FromArgb(20,30,50); $btnTabSec.ForeColor="LightSkyBlue"; $btnTabHard.BackColor="Transparent"; $btnTabHard.ForeColor="Gray" })

if (Test-Path $SecurityConfigPath) { 
    $SavedData = Get-Content $SecurityConfigPath
    if ($SavedData) { foreach ($s in $SavedData) { if ($s -and $s.Trim()) { $lstDomains.Items.Add($s) } } }
}
if ($lstDomains.Items.Count -eq 0) { @("*@outlook.com", "*@triveni-tech.in", "*@triveniglobalsoft.com", "*@supervedic.com") | ForEach-Object { $lstDomains.Items.Add($_) } }

$form.ShowDialog()
trap { Write-Host "ERROR: $($_.Exception.Message)" -ForegroundColor Red; Read-Host }